static size_t locale_index(const char *locale) {
    char tag[32]; size_t i = 0;
    if (locale == NULL) return 2;
    while (locale[i] && i < sizeof(tag)-1) {
        unsigned char c = (unsigned char)locale[i];
        tag[i] = c == '_' ? '-' : (c >= 'A' && c <= 'Z' ? (char)(c + ('a'-'A')) : (char)c); ++i;
    }
    tag[i] = '\0';
    if (!strcmp(tag,"zh") || !strcmp(tag,"zh-cn") || !strcmp(tag,"zh-sg") || !strcmp(tag,"zh-hans") || !strncmp(tag,"zh-hans-",8)) return 0;
    if (!strcmp(tag,"zh-tw") || !strcmp(tag,"zh-hk") || !strcmp(tag,"zh-mo") || !strcmp(tag,"zh-hant") || !strncmp(tag,"zh-hant-",8)) return 1;
    if (!strcmp(tag,"ja") || !strncmp(tag,"ja-",3)) return 3;
    return 2;
}
const char *env_text_get(const char *locale, const char *key) {
    size_t low=0, high=sizeof(texts)/sizeof(texts[0]);
    if (key == NULL) return NULL;
    while (low < high) {
        size_t mid=low+(high-low)/2; int cmp=strcmp(key,texts[mid].key);
        if (cmp == 0) return texts[mid].text[locale_index(locale)];
        if (cmp < 0) high=mid; else low=mid+1;
    }
    return NULL;
}
const char *env_text_rating_id(const char *metric, int rating) {
    size_t i; const char *fallback=NULL;
    if (metric == NULL) return NULL;
    for (i=0; i<sizeof(ratings)/sizeof(ratings[0]); ++i) {
        if (strcmp(metric,ratings[i].metric)) continue;
        if (ratings[i].value == rating) return ratings[i].id;
        if (!strcmp(ratings[i].id,"unknown")) fallback=ratings[i].id;
    }
    return fallback;
}
const char *env_text_get_rating(const char *locale, const char *metric, int rating, const char *field) {
    char key[128]; int size; const char *id=env_text_rating_id(metric,rating);
    if (id == NULL || field == NULL) return NULL;
    if (strcmp(field,"label") && strcmp(field,"summary") && strcmp(field,"detail")) return NULL;
    size=snprintf(key,sizeof(key),"env_%s_rating_%s_%s",metric,id,field);
    if (size < 0 || (size_t)size >= sizeof(key)) return NULL;
    return env_text_get(locale,key);
}
